grade.command_excerpt:
$samples = @(1..6 | ForEach-Object {
    $memory = Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory
    $cpu = Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'"
    [pscustomobject]@{
        Time = Get-Date -Format 'HH:mm:ss'
        Workers = @(Get-Process -Name ci-task -ErrorAction SilentlyContinue).Count
        CPUPercent = $cpu.PercentProcessorTime
        FreeMiB = $memory.AvailableMBytes
        CommitMiB = [math]::Round($memory.CommittedBytes / 1MB)
        NonpagedMiB = [math]::Round($memory.PoolNonpagedBytes / 1MB)
    }
    if ($_ -lt 6) { Start-Sleep -Seconds 5 }
})
$samples | Format-Table -AutoSize
$first = $samples[0]
$last = $samples[-1]
[pscustomobject]@{
    Workers = "$($first.Workers) -> $($last.Workers)"
    CPU = "$($first.CPUPercent)% -> $($last.CPUPercent)%"
    FreeDeltaMiB = $last.FreeMiB - $first.FreeMiB
    CommitDeltaMiB = $last.CommitMiB - $first.CommitMiB
    NonpagedDeltaMiB = $last.NonpagedMiB - $first.NonpagedMiB
} | Format-List

Get-Counter @('\Memory\Available MBytes','\Memory\Committed Bytes','\Processor(_Total)\% Processor Time') -SampleInterval 5 -MaxSamples 6 -ErrorAction Stop | ForEach-Object {
    $readings = $_.CounterSamples
    [pscustomobject]@{
        Time = $_.Timestamp
        FreeGiB = [math]::Round((($readings | Where-Object Path -Like '*\available mbytes').CookedValue / 1024), 2)
        CommitGiB = [math]::Round((($readings | Where-Object Path -Like '*\committed bytes').CookedValue / 1GB), 2)
        CPUPercent = [math]::Round(($readings | Where-Object Path -Like '*\% processor time').CookedValue, 1)
    }
} | Format-Table -AutoSize

Get-Counter @('\Memory\Available MBytes','\Memory\Committed Bytes','\Processor(_Total)\% Processor Time') -SampleInterval 5 -MaxSamples 6 -ErrorAction Stop | ForEach-Object {
    $c = $_.CounterSamples
    [pscustomobject]@{
        Time = $_.Timestamp
        FreeGiB = [math]::Round((($c | Where-Object Path -Like '*\available mbytes').CookedValue / 1024), 2)
        CommitGiB = [math]::Round((($c | Where-Object Path -Like '*\committed bytes').CookedValue / 1GB), 2)
        CPUPercent = [math]::Round(($c | Where-Object Path -Like '*\% processor time').CookedValue, 1)
    }
} | Format-Table -AutoSize
